// Exercises inside the units: checking with explanations, tap-to-match, tap-to-build word order,
// solution reveal, per-unit status and the end-of-unit summary. The exercise HTML is generated by
// tools/sitegen.py; answer keys come from course.json (items[slotId].a).
import { validate, isCorrect, CATEGORY_LABEL } from '../lib/validate.js';
import { shuffle } from '../lib/text.js';
import { unitStats, STATUS_LABEL, courseOrder, findUnit } from '../lib/progress.js';
import { $, $$, esc, pct, plural, el } from './dom.js';
import { addSpeakButtons } from './speech.js';

let C = null;   // ctx
const VAL = 'mh1:v:';   // typed answers keep the v1 keys, so nothing a learner typed before is lost

function ls() { return C.store.backend; }

function slotIds(ex) {
  return [...new Set($$('[data-slot]', ex).map(e => e.dataset.slot))].filter(s => C.course.items[s]);
}
function slotValue(ex, sid) {
  return $$(`[data-slot="${sid}"]`, ex).map(e => e.value.trim()).filter(Boolean).join(' ');
}
function slotHost(input) { return input.closest('.it,.mrow') || input; }

function feedbackHost(ex, sid) {
  const li = ex.querySelector(`[data-item="${sid}"]`);
  if (li) {
    let fb = li.querySelector(':scope > .ibody > .fb');
    if (!fb) { fb = el('<div class="fb" aria-live="polite"></div>'); li.querySelector('.ibody').appendChild(fb); }
    return fb;
  }
  // inline blanks in tables and running texts: one feedback list under the exercise
  let list = ex.querySelector('.exfb');
  if (!list) { list = el('<ul class="exfb" aria-live="polite"></ul>'); ex.querySelector('.exbar').before(list); }
  let fb = list.querySelector(`[data-fb="${sid}"]`);
  if (!fb) {
    const input = ex.querySelector(`[data-slot="${sid}"]`);
    fb = el(`<li class="fb" data-fb="${sid}"><span class="fbl">${esc(input?.getAttribute('aria-label') || '')}:</span> </li>`);
    list.appendChild(fb);
  }
  return fb;
}

function showFeedback(ex, sid, res) {
  const fb = feedbackHost(ex, sid);
  const keep = fb.querySelector('.fbl')?.outerHTML || '';
  if (res.verdict === 'empty') { fb.innerHTML = ''; if (fb.dataset.fb) fb.remove(); return; }
  if (res.verdict === 'ok') {
    fb.innerHTML = res.notes.length ? keep + `<span class="note-i">${esc(res.notes.join(' '))}</span>` : '';
    if (!res.notes.length && fb.dataset.fb) fb.remove();
    return;
  }
  if (res.verdict === 'near') { fb.innerHTML = keep + `<span class="note-i">${esc(res.notes.join(' '))}</span>`; return; }
  const extra = res.notes.length ? ` <span class="why" hidden>${esc(res.notes.join(' '))}</span>` : '';
  fb.innerHTML = keep + `<span class="msg">${esc(res.msg)}</span> <button type="button" class="link" data-act="reveal-item" data-sid="${sid}">Shiko përgjigjen</button>`
    + `<span class="ans" hidden>Përgjigjja: <b>${esc(res.alts.slice(0, 3).join(' · '))}</b></span>${extra}`;
}

function checkEx(ex, { record = true } = {}) {
  const sids = slotIds(ex);
  let ok = 0, near = 0;
  for (const sid of sids) {
    const value = slotValue(ex, sid);
    const res = validate(value, C.course.items[sid].a);
    const good = isCorrect(res);
    if (good) ok++;
    if (res.verdict === 'near') near++;
    new Set($$(`[data-slot="${sid}"]`, ex).map(slotHost)).forEach(h => {
      h.classList.remove('ok', 'bad', 'near');
      if (res.verdict !== 'empty') h.classList.add(good ? (res.verdict === 'near' ? 'near' : 'ok') : 'bad');
    });
    if (!ex.querySelector('.match.tiles') || !good) showFeedback(ex, sid, res);
    if (record && res.verdict !== 'empty') C.store.recordItem(sid, res, value, 'lesson');
  }
  const sc = ex.querySelector('.score');
  sc.textContent = `${ok} / ${sids.length} të sakta` + (near ? ` (${near} me shënim)` : '');
  sc.classList.toggle('full', ok === sids.length);
  if (record) C.store.recordExercise(ex.dataset.ex, ok, sids.length);
  const unit = ex.closest('article.unit');
  paintStatus(unit);
  paintDone(unit, true);
}

function clearEx(ex) {
  $$('[data-slot]', ex).forEach(e => { e.value = ''; ls().del(VAL + e.id); });
  $$('.ok,.bad,.near', ex).forEach(e => e.classList.remove('ok', 'bad', 'near'));
  $$('.fb', ex).forEach(f => { if (f.dataset.fb) f.remove(); else f.innerHTML = ''; });
  $$('.chip.used', ex).forEach(c => c.classList.remove('used'));
  ex.querySelector('.score').textContent = '';
  const sol = ex.querySelector('.sol'); sol.hidden = true;
  const sb = ex.querySelector('[data-act="show"]'); if (sb) sb.textContent = 'Shfaq zgjidhjen';
  C.store.clearExercise(ex.dataset.ex);
  $$('.match', ex).forEach(setupMatch);
  const unit = ex.closest('article.unit');
  paintStatus(unit); paintDone(unit, false);
}

// ---------------------------------------------------------------- tap-to-match
function setupMatch(box) {
  const ex = box.closest('.ex');
  const rows = $$('.mrow', box).map(r => ({ sel: r.querySelector('select'), html: r.querySelector('.mleft').innerHTML }));
  if (!rows.length || rows.some(r => !C.course.items[r.sel.dataset.slot])) return;
  const slotOk = (sid, v) => isCorrect(validate(v, C.course.items[sid].a));
  box.classList.add('tiles');
  const ins = box.previousElementSibling;
  if (ins && ins.matches('p.instr') && /^Lidhni me vijë/.test(ins.textContent)) ins.textContent = 'Prekni një kuti majtas, pastaj kutinë që i përket djathtas.';
  box.querySelector('.mm')?.remove();
  const opts = [...rows[0].sel.options].map(o => o.value).filter(Boolean);
  const mm = el('<div class="mm"></div>');
  const L = el('<div class="mm-col"></div>'), R = el('<div class="mm-col"></div>');
  let pick = null, misses = 0;
  const tile = html => { const b = document.createElement('button'); b.type = 'button'; b.className = 'mt'; b.innerHTML = html; b.setAttribute('aria-pressed', 'false'); return b; };
  const lefts = rows.map(r => { const b = tile(r.html); b.row = r; L.appendChild(b); return b; });
  // one answer tile per row, so repeated answers (jij/hij → spreekt) appear once for each row
  const answers = rows.map(r => opts.find(o => slotOk(r.sel.dataset.slot, o))).filter(Boolean);
  const rights = shuffle(answers).map(o => { const b = tile(''); b.textContent = o; b.opt = o; R.appendChild(b); return b; });
  const open = () => lefts.filter(b => !b.classList.contains('mt-ok'));
  const select = b => { if (pick) { pick.classList.remove('mt-sel'); pick.setAttribute('aria-pressed', 'false'); } pick = b; if (b) { b.classList.add('mt-sel'); b.setAttribute('aria-pressed', 'true'); } };
  const settle = () => {
    if (!open().length) { checkEx(ex); if (misses) ex.querySelector('.score').textContent += ' · ' + plural(misses, 'gabim', 'gabime'); }
  };
  const use = rb => { rb.disabled = true; rb.classList.add('mt-ok', 'mt-done'); rb.classList.remove('mt-sel'); };
  const lock = (lb, opt) => {
    lb.row.sel.value = opt; ls().set(VAL + lb.row.sel.id, opt);
    lb.disabled = true; lb.classList.add('mt-ok', 'mt-done'); lb.classList.remove('mt-sel');
    lb.setAttribute('aria-label', lb.textContent + ' – ' + opt);
  };
  const flash = (...bs) => bs.forEach(b => { b.classList.remove('mt-sel'); b.classList.add('mt-no'); setTimeout(() => b.classList.remove('mt-no'), 450); });
  const choose = b => {
    if (b.disabled) return;
    if (!pick || pick === b || (lefts.includes(pick) === lefts.includes(b))) { select(pick === b ? null : b); return; }
    const lb = lefts.includes(b) ? b : pick, rb = lefts.includes(b) ? pick : b;
    select(null);
    if (slotOk(lb.row.sel.dataset.slot, rb.opt)) { lock(lb, rb.opt); use(rb); settle(); }
    else {
      misses++; flash(lb, rb);
      // a wrong pairing is a real mistake: it goes into the history and the review queue
      C.store.recordItem(lb.row.sel.dataset.slot, validate(rb.opt, C.course.items[lb.row.sel.dataset.slot].a), rb.opt, 'match');
    }
  };
  [...lefts, ...rights].forEach(b => b.addEventListener('click', () => choose(b)));
  lefts.forEach(lb => {
    const v = lb.row.sel.value, rb = v && rights.find(r => !r.disabled && r.opt === v);
    if (rb && slotOk(lb.row.sel.dataset.slot, v)) { lock(lb, v); use(rb); }
    else if (v) { lb.row.sel.value = ''; ls().del(VAL + lb.row.sel.id); }
  });
  mm.append(L, R); box.appendChild(mm);
}

// ---------------------------------------------------------------- tap-to-build word order
function chipClick(chip) {
  const li = chip.closest('.it');
  const input = li?.querySelector('input.full');
  if (!input) return;
  if (chip.classList.contains('used')) return;
  input.value = (input.value.trim() + ' ' + chip.textContent.trim()).trim();
  chip.classList.add('used');
  input.dispatchEvent(new Event('input', { bubbles: true }));
  ensureUndo(li);
}
function ensureUndo(li) {
  if (li.querySelector('.chipctl')) return;
  const ctl = el('<div class="chipctl"><button type="button" class="link" data-act="chip-undo">↶ Hiq fjalën e fundit</button><button type="button" class="link" data-act="chip-reset">Fillo nga e para</button></div>');
  li.querySelector('.chips').after(ctl);
}
function chipUndo(li, all) {
  const input = li.querySelector('input.full');
  const used = $$('.chip.used', li);
  if (all) { input.value = ''; used.forEach(c => c.classList.remove('used')); }
  else {
    const words = input.value.trim().split(/\s+/);
    // remove the last chip's words (chips can hold several words: "een boek")
    for (let i = used.length - 1; i >= 0; i--) {
      const w = used[i].textContent.trim().split(/\s+/);
      if (words.slice(-w.length).join(' ') === w.join(' ')) { words.splice(-w.length); used[i].classList.remove('used'); break; }
    }
    input.value = words.join(' ');
  }
  input.dispatchEvent(new Event('input', { bubbles: true }));
}
function syncChips(li) {
  // chips typed by hand count as used too
  const input = li.querySelector('input.full');
  const v = ' ' + input.value.toLowerCase().replace(/[.,!?]/g, ' ') + ' ';
  let rest = v;
  $$('.chip', li).forEach(c => {
    const w = ' ' + c.textContent.trim().toLowerCase() + ' ';
    if (rest.includes(w)) { c.classList.add('used'); rest = rest.replace(w, ' '); } else c.classList.remove('used');
  });
}

// ---------------------------------------------------------------- unit status and summary
export function paintStatus(art) {
  const box = art?.querySelector('[data-status]');
  if (!box) return;
  const s = unitStats(C.store.state, C.course, box.dataset.status);
  if (!s.exercises) { box.innerHTML = ''; return; }
  const bar = s.items ? Math.round((s.attempted / s.items) * 100) : 0;
  box.innerHTML = `<span class="st st-${s.status}">${STATUS_LABEL[s.status]}</span>
    <span class="bar" role="img" aria-label="${bar} % e pikave të provuara"><i style="width:${bar}%"></i></span>
    <span class="muted">${s.checked}/${s.exercises} ushtrime · saktësia në provën e parë ${pct(s.accuracy)}</span>`;
}

function nextOf(code) {
  const order = courseOrder(C.course);
  const i = order.indexOf(code);
  return i >= 0 && i < order.length - 1 ? findUnit(C.course, order[i + 1]) : null;
}

function paintDone(art, scroll) {
  const box = art?.querySelector('[data-done]');
  if (!box) return;
  const code = box.dataset.done;
  const s = unitStats(C.store.state, C.course, code);
  if (!s.completed) { box.hidden = true; box.innerHTML = ''; return; }
  const wasHidden = box.hidden;
  const wrong = $$('.ex', art).flatMap(ex => slotIds(ex).map(sid => ({ sid, ex, v: slotValue(ex, sid) })))
    .map(o => ({ ...o, res: validate(o.v, C.course.items[o.sid].a) }))
    .filter(o => !isCorrect(o.res));
  const mastery = C.store.state.settings.mastery;
  const good = s.accuracy !== null && s.accuracy >= mastery;
  const next = nextOf(code);
  const rows = wrong.slice(0, 30).map(o => {
    const it = C.course.items[o.sid];
    const exm = C.course.exercises[it.ex];
    return `<li><div class="wq"><span class="tag">${esc(exm.letter)}</span> ${it.p || esc(exm.title)}</div>
      <div class="wa">Ju: <s>${esc(o.v || '— bosh —')}</s> → <b>${esc(o.res.alts.slice(0, 2).join(' · '))}</b></div>
      ${o.res.msg ? `<div class="muted">${esc(o.res.msg)}${o.res.cat ? ` <span class="tag">${esc(CATEGORY_LABEL[o.res.cat] || '')}</span>` : ''}</div>` : ''}</li>`;
  }).join('');
  box.innerHTML = `<div class="done-card ${good ? 'is-good' : 'is-review'}" tabindex="-1">
    <div class="lk">Njësia u përfundua</div>
    <h3>${good ? 'Shumë mirë!' : 'U përfundua – por ia vlen një përsëritje'}</h3>
    <div class="done-stats">
      <div><b>${pct(s.accuracy)}</b><span>saktë në provën e parë</span></div>
      <div><b>${s.now}/${s.items}</b><span>të sakta tani</span></div>
      <div><b>${wrong.length}</b><span>${wrong.length === 1 ? 'gabim i mbetur' : 'gabime të mbetura'}</span></div>
    </div>
    <p>${good
      ? `Kaluat pragun prej ${Math.round(mastery * 100)} % në provën e parë. Fjalët e reja të njësisë shtohen te fjalori për përsëritje.`
      : `Pragu për ta konsideruar njësinë të zotëruar është ${Math.round(mastery * 100)} % në provën e parë. Rilexoni rregullat te mësimet dhe përsëritni gabimet – sistemi do t'jua sjellë sërish pas disa ditësh.`}</p>
    ${wrong.length ? `<h4>Gabimet</h4><ol class="wrong">${rows}</ol>${wrong.length > 30 ? `<p class="muted">… dhe ${wrong.length - 30} të tjera.</p>` : ''}` : ''}
    <div class="exbar">
      ${wrong.length ? `<a class="btn primary" href="#praktike/gabimet/${code}">Përsërit gabimet</a>` : ''}
      <button type="button" class="btn" data-act="retry-unit">Provo sërish gjithë ushtrimet</button>
      ${next ? `<a class="btn ${wrong.length ? '' : 'primary'}" href="#${next.id}">Vazhdo: ${esc(next.n ? 'Njësia ' + next.n : next.title)} →</a>` : ''}
    </div></div>`;
  box.hidden = false;
  if (scroll && wasHidden) requestAnimationFrame(() => { box.scrollIntoView({ block: 'nearest' }); box.firstElementChild.focus({ preventScroll: true }); });
}

export function paintRail(ctx) {
  C = ctx;
  $$('[data-prog]').forEach(sp => {
    const s = unitStats(C.store.state, C.course, sp.dataset.prog);
    sp.textContent = s.status === 'mastered' ? '✓' : s.status === 'review' ? '↻' : s.attempted ? `${Math.round((s.attempted / Math.max(1, s.items)) * 100)}%` : '';
    sp.title = STATUS_LABEL[s.status];
  });
}

export function onShow(art, ctx, anchor) {
  C = ctx;
  C.store.visit(art.id, anchor);
  if (!art.dataset.ready) {
    art.dataset.ready = '1';
    $$('.ex', art).forEach(ex => {
      if (C.store.state.ex[ex.dataset.ex]) checkEx(ex, { record: false });
    });
    addSpeakButtons(art, C);
  }
  paintStatus(art);
  paintDone(art, false);
}

export function init(ctx) {
  C = ctx;
  // restore what the learner typed
  $$('[data-slot]').forEach(e => { const v = ls().get(VAL + e.id); if (v !== null) e.value = v; });
  $$('.orders .it').forEach(li => { if (li.querySelector('input.full').value) { syncChips(li); ensureUndo(li); } });
  $$('.match').forEach(setupMatch);
  paintRail(ctx);
  document.addEventListener('click', e => {
    const chip = e.target.closest('[data-chip]');
    if (chip) { chipClick(chip); return; }
    const b = e.target.closest('[data-act]');
    if (!b) return;
    const ex = b.closest('.ex');
    const act = b.dataset.act;
    if (act === 'check') checkEx(ex);
    else if (act === 'show') {
      const s = ex.querySelector('.sol');
      s.hidden = !s.hidden;
      b.textContent = s.hidden ? 'Shfaq zgjidhjen' : 'Fshih zgjidhjen';
      if (!s.hidden) C.store.reveal(ex.dataset.ex, slotIds(ex));
    } else if (act === 'clear') clearEx(ex);
    else if (act === 'reveal-item') {
      const fb = b.closest('.fb');
      fb.querySelector('.ans').hidden = false;
      const why = fb.querySelector('.why'); if (why) why.hidden = false;
      b.remove();
      C.store.reveal(ex.dataset.ex, [b.dataset.sid]);
    } else if (act === 'chip-undo') chipUndo(b.closest('.it'), false);
    else if (act === 'chip-reset') chipUndo(b.closest('.it'), true);
    else if (act === 'retry-unit') {
      const art = b.closest('article.unit');
      $$('.ex', art).forEach(clearEx);
      art.querySelector('.ex')?.scrollIntoView();
      art.querySelector('.ex [data-slot]')?.focus({ preventScroll: true });
    }
  });
  document.addEventListener('input', e => {
    const t = e.target;
    if (!t.dataset || !t.dataset.slot) return;
    ls().set(VAL + t.id, t.value);
    const h = slotHost(t); h.classList.remove('ok', 'bad', 'near');
    if (t.matches('.orders input.full')) syncChips(t.closest('.it'));
  });
  document.addEventListener('change', e => {
    const t = e.target;
    if (t.tagName === 'SELECT' && t.dataset.slot) { ls().set(VAL + t.id, t.value); slotHost(t).classList.remove('ok', 'bad', 'near'); }
  });
  // Enter in a single answer field checks the exercise
  document.addEventListener('keydown', e => {
    if (e.key !== 'Enter' || !e.target.dataset?.slot || e.target.tagName !== 'INPUT') return;
    const ex = e.target.closest('.ex');
    if (!ex) return;
    const inputs = $$('input[data-slot]', ex);
    const i = inputs.indexOf(e.target);
    e.preventDefault();
    if (i < inputs.length - 1) inputs[i + 1].focus(); else checkEx(ex);
  });
}
